import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> Any:
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"', strict=False)

    records = []
    for record in reader:
        if not record:
            continue
        records.append([str(value) for value in record])

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    width = len(columns)
    rows = []

    for record in records[1:]:
        if len(record) < width:
            record.extend([""] * (width - len(record)))
        elif len(record) > width and width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
